using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchive now writes UTF-8 by default
        // (sets the EFS/Language encoding flag). The legacy Java consumer
        // expects Shift-JIS filenames, so we must specify the encoding
        // explicitly to suppress the UTF-8 flag.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding("shift_jis")
            ?? Encoding.UTF8;
        using var stream = File.Create("data.zip");
        using var archive = new ZipArchive(stream, ZipArchiveMode.Create,
            leaveOpen: false, entryNameEncoding: shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: [FromKeyedServices("cache")] now throws
// InvalidOperationException if the service is registered as non-keyed.
// Register with the matching key.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

